insert into public.lesson_content (lesson_id, video, blocks) values ('d74e37e0-abfe-5ff1-a610-454375002940', $j${"provider":"file","src":"https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4","duration":596,"chapters":[{"t":0,"title":"Welcome"},{"t":90,"title":"Your workspace"},{"t":230,"title":"Hygiene essentials"},{"t":410,"title":"Client safety"}],"transcript":[{"t":0,"text":"Welcome to the academy. In this lesson we set up your station the way a pro does it."},{"t":24,"text":"A great set starts long before the first lash. It starts with a calm, clean workspace."},{"t":60,"text":"Lay out your tweezers, adhesive, tray and cleanser in the order you will reach for them."},{"t":100,"text":"Shake your adhesive well and drop a fresh amount onto a jade stone or tile every 30 minutes."},{"t":150,"text":"Keep the bottle tight between uses. Air and humidity are the enemies of a strong bond."},{"t":235,"text":"Sanitise your hands, your tweezers and every surface your client might touch."},{"t":300,"text":"Never reuse a disposable. Single-use means single-use, every time."},{"t":415,"text":"Ask about allergies and sensitivities before you begin, and patch test when in doubt."},{"t":500,"text":"If your client feels any stinging, stop, remove and reassess. Comfort comes first."}],"products":[{"t":100,"slug":"pro-bond-adhesive-5ml","note":"The adhesive used in this lesson"}]}$j$::jsonb, $j$[{"type":"heading","text":"The three rules of a safe station"},{"type":"list","style":"numbered","items":["**Clean** everything that touches your client","**Fresh** adhesive and fresh disposables","**Calm** pace, because rushing causes mistakes"]},{"type":"callout","tone":"tip","title":"Pro tip","text":"Set a 30 minute timer on your phone as a reminder to refresh your adhesive drop."}]$j$::jsonb)
on conflict (lesson_id) do update set video = excluded.video, blocks = excluded.blocks;
