insert into public.lesson_content (lesson_id, video, blocks) values ('495ab78c-1ac9-5496-a073-b1c4fcb496aa', null, $j$[{"type":"text","text":"Retention is decided in the first ten minutes of an appointment. Before a single extension touches a natural lash, the lash bed has to be clean, dry and oil free."},{"type":"heading","text":"Start with a clean canvas"},{"type":"text","text":"Natural oils, sunscreen and makeup residue are the number one cause of early lash loss. Cleanse every client, even the ones who arrive 'bare faced'."},{"type":"flip","prompt":"Myth or fact?","front":"Clients who arrive bare faced don't need cleansing.","back":"Natural oils and sunscreen still cause early lash loss. **Cleanse every client.**"},{"type":"figure","url":"data:image/svg+xml;utf8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20800%20450%22%3E%3Crect%20width%3D%22800%22%20height%3D%22450%22%20fill%3D%22%23F3E4E7%22%2F%3E%3Cg%20fill%3D%22none%22%20stroke%3D%22%23C9707F%22%20stroke-width%3D%223%22%20stroke-linecap%3D%22round%22%3E%3Cpath%20d%3D%22M120%20250%20Q400%2090%20680%20250%20Q400%20380%20120%20250Z%22%2F%3E%3Ccircle%20cx%3D%22400%22%20cy%3D%22240%22%20r%3D%2262%22%2F%3E%3Ccircle%20cx%3D%22400%22%20cy%3D%22240%22%20r%3D%2222%22%2F%3E%3Cpath%20d%3D%22M190%20215%20l-26%20-52%22%2F%3E%3Cpath%20d%3D%22M242%20203.5194970290473%20l-20%20-52%22%2F%3E%3Cpath%20d%3D%22M294%20193.78679656440357%20l-14%20-52%22%2F%3E%3Cpath%20d%3D%22M346%20187.2836140246614%20l-8%20-52%22%2F%3E%3Cpath%20d%3D%22M398%20185%20l-2%20-52%22%2F%3E%3Cpath%20d%3D%22M450%20187.2836140246614%20l4%20-52%22%2F%3E%3Cpath%20d%3D%22M502%20193.78679656440357%20l10%20-52%22%2F%3E%3Cpath%20d%3D%22M554%20203.5194970290473%20l16%20-52%22%2F%3E%3Cpath%20d%3D%22M606%20215%20l22%20-52%22%2F%3E%3C%2Fg%3E%3C%2Fsvg%3E","caption":"Lash line, upper lid, and where cleansing stops."},{"type":"steps","items":[{"title":"Remove makeup","text":"Use an oil free remover on a lint free pad, working from the inner corner outward."},{"title":"Foam cleanse","text":"Apply lash cleanser with a soft brush along the base of the lashes."},{"title":"Rinse and dry","text":"Rinse with a damp pad, then dry completely with a gentle fan."}]},{"type":"callout","tone":"mistake","title":"Common mistake","text":"Skipping the dry step. Even slightly damp lashes will weaken the adhesive bond."},{"type":"heading","text":"Primer and isolation"},{"type":"text","text":"A primer prepares the lash surface for the adhesive. Apply a **thin, even** layer and allow it to flash dry before you begin."},{"type":"quote","text":"Retention is built in preparation, not repaired in the fill.","by":"Lashtribe Academy"},{"type":"checkpoint","question":"What should you do right after rinsing the lash bed?","options":["Apply adhesive immediately","Dry completely before primer","Apply a second cleanse"],"answer":1,"explain":"Moisture weakens the bond, so the lashes must be completely dry before primer or adhesive."},{"type":"heading","text":"Your 60 second checklist"},{"type":"list","style":"checklist","items":["Makeup and oils removed","Cleansed and rinsed","Completely dry","Primer applied and flash dried","Under eye pads placed smoothly"]},{"type":"callout","tone":"key","title":"Remember","text":"Clean, dry and primed. If you do nothing else, do these three."}]$j$::jsonb)
on conflict (lesson_id) do update set video = excluded.video, blocks = excluded.blocks;

