insert into public.lesson_content (lesson_id, video, blocks) values ('4333b08c-c011-560b-a671-98de8ad74830', $j${"provider":"file","src":"https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ElephantsDream.mp4","duration":653,"chapters":[{"t":0,"title":"What makes a good fan"},{"t":120,"title":"Picking up a clean fan"},{"t":300,"title":"Pinching the base"},{"t":480,"title":"Troubleshooting"}],"transcript":[{"t":0,"text":"A handmade fan is simply several thin extensions joined at a narrow base."},{"t":40,"text":"You are looking for an even spread and a base that looks like a single point."},{"t":125,"text":"Pick up two to five lashes from the tray with your tweezers, using a soft grip."},{"t":190,"text":"Let the lashes fall open naturally rather than forcing them apart."},{"t":305,"text":"Gently pinch a few millimetres above the base to set the fan."},{"t":380,"text":"Use fresh tray fans for practice. They stay lined up and easier to handle."},{"t":485,"text":"If the fan looks wide on one side, let it go and pick up again."},{"t":560,"text":"Consistency beats speed. Speed will come with repetition."}],"products":[{"t":125,"slug":"0-07-volume-fans-mixed-tray","note":"Great for practising fan pick up"},{"t":305,"slug":"isolation-tweezers-curved","note":"The tweezers used here"}]}$j$::jsonb, $j$[{"type":"heading","text":"What to look for"},{"type":"figure","url":"data:image/svg+xml;utf8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20800%20450%22%3E%3Crect%20width%3D%22800%22%20height%3D%22450%22%20fill%3D%22%23F3E4E7%22%2F%3E%3Cg%20fill%3D%22none%22%20stroke%3D%22%23C9707F%22%20stroke-width%3D%223%22%20stroke-linecap%3D%22round%22%3E%3Cpath%20d%3D%22M400%20380%20L400%20250%22%2F%3E%3Cpath%20d%3D%22M400%20250%20Q288%20180%20152%20110%22%2F%3E%3Cpath%20d%3D%22M400%20250%20Q316%20180%20214%20110%22%2F%3E%3Cpath%20d%3D%22M400%20250%20Q344%20180%20276%20110%22%2F%3E%3Cpath%20d%3D%22M400%20250%20Q372%20180%20338%20110%22%2F%3E%3Cpath%20d%3D%22M400%20250%20Q400%20180%20400%20110%22%2F%3E%3Cpath%20d%3D%22M400%20250%20Q428%20180%20462%20110%22%2F%3E%3Cpath%20d%3D%22M400%20250%20Q456%20180%20524%20110%22%2F%3E%3Cpath%20d%3D%22M400%20250%20Q484%20180%20586%20110%22%2F%3E%3Cpath%20d%3D%22M400%20250%20Q512%20180%20648%20110%22%2F%3E%3C%2Fg%3E%3C%2Fsvg%3E","caption":"A clean fan has an even spread and one narrow base."},{"type":"callout","tone":"tip","title":"Pro tip","text":"Practise on a mannequin for 15 minutes before every client for the first month."}]$j$::jsonb)
on conflict (lesson_id) do update set video = excluded.video, blocks = excluded.blocks;
