insert into public.lesson_content (lesson_id, video, blocks) values ('700756eb-e725-5457-ab99-bf81a6fb6599', $j${"provider":"file","src":"https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/Sintel.mp4","duration":888,"chapters":[{"t":0,"title":"Why isolation matters"},{"t":200,"title":"Tweezer angles"},{"t":520,"title":"Live demo"}],"transcript":[{"t":0,"text":"Isolation is the skill every other skill depends on."},{"t":60,"text":"If you stick two natural lashes together the client will feel it within days."},{"t":205,"text":"Hold your isolation tweezer flat and slide under one lash at a time."},{"t":330,"text":"Use the lash line as a guide, and check from both sides."},{"t":525,"text":"Now watch the full sequence at normal speed."}],"products":[]}$j$::jsonb, $j$[]$j$::jsonb)
