insert into public.lesson_content (lesson_id, video, blocks) values ('dea23358-fd04-5f54-a367-5ebdb567c2f4', null, $j$[{"type":"quiz","passScore":60,"questions":[{"q":"How often should you refresh the adhesive drop during a set?","options":["Once per day","About every 30 minutes","Only when it runs out"],"answer":1,"explain":"Adhesive cures and loses strength as it sits in open air, so refresh it regularly."},{"q":"What makes a handmade fan look professional?","options":["A very wide base","An even spread and a narrow base","As many lashes as possible"],"answer":1,"explain":"The base should read as a single point so the fan sits neatly on one natural lash."},{"q":"A client reports stinging during a set. What is the first step?","options":["Continue quickly","Stop and reassess","Add more primer"],"answer":1,"explain":"Comfort and safety come first. Stop and reassess before continuing."},{"q":"Why is isolation so important?","options":["It makes sets look fuller","It prevents lashes sticking together","It speeds up application"],"answer":1,"explain":"Stuck natural lashes pull and break, causing discomfort and early shedding."},{"q":"Which should always be dry before adhesive is applied?","options":["The tray","The lash bed","The mannequin"],"answer":1,"explain":"A completely dry lash bed gives the adhesive a strong bond."}]}]$j$::jsonb)
on conflict (lesson_id) do update set video = excluded.video, blocks = excluded.blocks;

