insert into public.lesson_content (lesson_id, video, blocks) values ('82000a80-c0a8-5cfe-a91d-761d19311c9e', null, $j$[{"type":"text","text":"Adhesive is the most sensitive product on your trolley. Heat, humidity and air all change how it cures, so handling it well matters as much as how you apply it."},{"type":"heading","text":"Where to keep it"},{"type":"figure","url":"data:image/svg+xml;utf8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20800%20450%22%3E%3Crect%20width%3D%22800%22%20height%3D%22450%22%20fill%3D%22%23F3E4E7%22%2F%3E%3Cg%20fill%3D%22none%22%20stroke%3D%22%23C9707F%22%20stroke-width%3D%223%22%20stroke-linecap%3D%22round%22%3E%3Cpath%20d%3D%22M400%2090%20Q520%20250%20400%20330%20Q280%20250%20400%2090Z%22%2F%3E%3Cpath%20d%3D%22M340%20270%20Q360%20300%20400%20300%22%2F%3E%3C%2Fg%3E%3C%2Fsvg%3E","caption":"Store upright, sealed, and away from sunlight."},{"type":"list","style":"bullets","items":["Cool, dry place away from direct sun","Upright, with the cap tightly closed","Sealed in an airtight container with silica gel"]},{"type":"callout","tone":"tip","title":"Pro tip","text":"Write the date you open each bottle on the label, and replace it after about a month."},{"type":"flip","prompt":"Myth or fact?","front":"Adhesive cures fastest in a very dry room.","back":"Humidity speeds up curing. Most adhesives work best in **moderate humidity**, so check your room."},{"type":"heading","text":"Working with it"},{"type":"steps","items":[{"title":"Shake","text":"Shake the bottle for at least 30 seconds before each use."},{"title":"Drop","text":"Place a small drop on a clean surface and refresh every 30 minutes."},{"title":"Wipe","text":"Wipe the nozzle clean after every use to prevent clogging."}]},{"type":"checkpoint","question":"Where is the best place to store adhesive?","options":["On the window sill","Cool, dry and sealed","In the fridge, uncovered"],"answer":1,"explain":"Cool, dry and sealed keeps the adhesive from curing early."}]$j$::jsonb)
on conflict (lesson_id) do update set video = excluded.video, blocks = excluded.blocks;
