insert into public.lesson_content (lesson_id, video, blocks) values ('9042add5-59a6-5824-aefa-f9b3f636e977', null, $j$[{"type":"text","text":"Your tweezers are your most personal tool. A well looked after pair lasts for years and keeps your isolation precise."},{"type":"heading","text":"Cleaning after every client"},{"type":"figure","url":"data:image/svg+xml;utf8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20800%20450%22%3E%3Crect%20width%3D%22800%22%20height%3D%22450%22%20fill%3D%22%23F3E4E7%22%2F%3E%3Cg%20fill%3D%22none%22%20stroke%3D%22%23C9707F%22%20stroke-width%3D%223%22%20stroke-linecap%3D%22round%22%3E%3Cpath%20d%3D%22M180%20360%20L520%20190%20L640%20150%22%2F%3E%3Cpath%20d%3D%22M200%20395%20L540%20210%20L650%20170%22%2F%3E%3Cpath%20d%3D%22M520%20190%20Q560%20170%20640%20150%22%2F%3E%3C%2Fg%3E%3C%2Fsvg%3E","caption":"Tips should meet evenly with no gap."},{"type":"steps","items":[{"title":"Remove residue","text":"Wipe away adhesive with a lint free pad and remover."},{"title":"Disinfect","text":"Soak in hospital grade disinfectant for the recommended time."},{"title":"Dry and store","text":"Dry completely and store in a clean, closed case."}]},{"type":"compare","title":"Handling your tweezers","do":["Store them in a closed case","Disinfect after every client","Check the tips meet evenly"],"dont":["Drop them on a hard floor","Share them between technicians","Use them to open bottles"]},{"type":"callout","tone":"mistake","title":"Common mistake","text":"Dropping tweezers onto a hard floor. Even a small bend in the tip will affect isolation."},{"type":"callout","tone":"key","title":"Remember","text":"Clean after every client and never share tweezers between technicians."}]$j$::jsonb)
on conflict (lesson_id) do update set video = excluded.video, blocks = excluded.blocks;

